  var a=read(base,PC);var b=read(jar,PC);for(boolean world:new boolean[]{false,true}){var old=a.methods.stream().filter(m->m.name.equals(world?"useClassicWorldCenteredFreezeAttackSpell":"useCenteredFreezeAttackSpell")).findFirst().orElseThrow();var expected=originalReplay(old,world);var actual=b.methods.stream().filter(m->m.name.equals("nativeAreaFreezeAccepted"+(world?"World":"Battle"))).findFirst().orElseThrow();int count=0;for(var n:actual.instructions)if(n instanceof MethodInsnNode c&&c.owner.equals(H)&&c.name.equals("duration")){if(!c.desc.equals("(L"+SP+";)I"))throw new AssertionError("frozen duration projection");c.owner=SP;c.name="durationSeconds";c.desc="()I";c.setOpcode(INVOKEVIRTUAL);count++;}if(count!=3||!Arrays.equals(body(b,expected,"replay",0),body(b,actual,"replay",0)))throw new AssertionError("original status/factory/palette/paralysis body changed");}
  var ctx=read(jar,CTX);var copy=ctx.methods.stream().filter(m->m.name.equals("<init>")&&m.desc.equals("(L"+CTX+";)V")).findFirst().orElseThrow();var writes=new HashSet<String>();int gets=0;for(var n:copy.instructions)if(n instanceof FieldInsnNode f){if(!f.owner.equals(CTX))throw new AssertionError();if(f.getOpcode()==PUTFIELD){if(!writes.add(f.name))throw new AssertionError();}else if(f.getOpcode()==GETFIELD)gets++;else throw new AssertionError();}if(writes.size()!=ctx.fields.stream().filter(f->(f.access&ACC_STATIC)==0).count()||gets!=writes.size()-1)throw new AssertionError("all captured data shared; exactly one fresh bounded plan slot");
